<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: ['auth', 'admin'] })
const route = useRoute()
const { data, refresh } = await useFetch<any>(`/api/admin/orders/${route.params.id}`)
const note = ref(''); const errorMessage = ref(''); const checklistError = ref('')
const statusText: Record<string, string> = { PENDING: '待确认', ACCEPTED: '已接单', PREPARING: '准备中', COMPLETED: '已完成', REJECTED: '已拒绝', CANCELLED: '用户取消' }
const ratingText: Record<string, string> = { GOOD: '好评 🥰', NEUTRAL: '中评 🙂', BAD: '差评 🥺' }
const actions: Record<string, { to: string, label: string, class: string }[]> = { PENDING: [{ to: 'ACCEPTED', label: '接下这单', class: 'bg-mint' }, { to: 'REJECTED', label: '暂时做不了', class: 'bg-peach' }], ACCEPTED: [{ to: 'PREPARING', label: '开始备菜', class: 'bg-lemon' }, { to: 'REJECTED', label: '临时拒绝', class: 'bg-peach' }], PREPARING: [{ to: 'COMPLETED', label: '完成，开饭！', class: 'bg-mint' }] }
const preparedCount = computed(() => data.value?.order?.ingredients?.filter((item: any) => item.checked).length || 0)
async function transition(toStatus: string) { try { await $fetch(`/api/admin/orders/${route.params.id}/transition`, { method: 'POST', body: { toStatus, note: note.value } }); note.value = ''; errorMessage.value = ''; await refresh() } catch (error: any) { errorMessage.value = error?.data?.message || error?.data?.statusMessage || '状态更新失败' } }
async function toggleIngredient(item: any) { checklistError.value = ''; try { await $fetch(`/api/admin/orders/${route.params.id}/ingredients`, { method: 'PATCH', body: { name: item.name, unit: item.unit, checked: !item.checked } }); await refresh() } catch (error: any) { checklistError.value = error?.data?.statusMessage || error?.data?.message || '食材状态保存失败' } }
</script>

<template><div class="mx-auto max-w-6xl"><NuxtLink to="/admin/orders" class="font-black underline">← 返回点单</NuxtLink><div v-if="data?.order" class="mt-6 grid gap-6 lg:grid-cols-[1fr_22rem]"><div class="space-y-6"><section class="sticker-card bg-lemon p-6"><div class="flex items-center justify-between gap-3"><div><p class="font-black">订单 #{{ data.order.id }} · {{ data.order.userName }}</p><h1 class="mt-2 text-3xl font-black">{{ statusText[data.order.status] }}</h1></div><div class="text-right font-black"><p>{{ data.order.scheduledDate }}</p><p>{{ data.order.mealSlot === 'LUNCH' ? '午餐' : '晚餐' }}</p></div></div><p v-if="data.order.note" class="mt-4 rounded-xl bg-white/70 p-3 font-semibold">留言：“{{ data.order.note }}”</p></section><section class="sticker-card p-5"><div class="flex items-end justify-between gap-3"><div><h2 class="text-xl font-black">备菜采购清单</h2><p class="mt-1 text-sm font-semibold text-ink/60">所有菜品用量已经自动合并，买到一项就勾一项。</p></div><strong class="shrink-0 text-sm">{{ preparedCount }}/{{ data.order.ingredients.length }} 已准备</strong></div><div class="mt-4 space-y-2"><label v-for="item in data.order.ingredients" :key="`${item.name}-${item.unit}`" class="flex cursor-pointer items-center gap-3 rounded-xl border-2 border-ink/15 p-3 transition hover:bg-lemon/40" :class="item.checked ? 'bg-mint/35' : 'bg-white'"><input type="checkbox" class="size-5 accent-[var(--color-ink)]" :checked="item.checked" @change="toggleIngredient(item)"><span class="min-w-0 flex-1" :class="item.checked ? 'line-through opacity-60' : ''"><strong>{{ item.name }}</strong><span class="ml-2 text-sm font-bold text-ink/65">{{ item.amount }}{{ item.unit }}</span></span><span v-if="item.checked" class="text-lg">✅</span></label></div><p v-if="!data.order.ingredients.length" class="mt-4 rounded-xl bg-lemon/40 p-4 text-center font-semibold">这些菜还没有登记食材配方。</p><p v-if="checklistError" class="mt-3 font-bold text-danger">{{ checklistError }}</p></section><section class="sticker-card p-5"><h2 class="text-xl font-black">菜品与当前食谱</h2><div v-for="item in data.order.items" :key="item.id" class="mt-3 flex justify-between border-b border-ink/15 pb-3"><NuxtLink v-if="item.dishId" :to="`/admin/dishes/${item.dishId}`" class="font-black underline">{{ item.dishName }}</NuxtLink><strong v-else>{{ item.dishName }}</strong><span class="font-black">× {{ item.quantity }}</span></div></section><section v-if="data.order.rating" class="sticker-card bg-peach p-5"><h2 class="text-xl font-black">她的饭后反馈</h2><p class="mt-3 text-2xl font-black">{{ ratingText[data.order.rating.rating] }}</p></section></div><aside><section class="sticker-card p-5"><h2 class="text-xl font-black">大厨操作台</h2><textarea v-model="note" class="form-field mt-4 min-h-24" maxlength="300" placeholder="给她留句话，可选" /><p v-if="errorMessage" class="mt-3 font-bold text-danger">{{ errorMessage }}</p><div class="mt-4 space-y-3"><button v-for="action in actions[data.order.status] || []" :key="action.to" class="sticker-button w-full" :class="action.class" @click="transition(action.to)">{{ action.label }}</button><p v-if="!(actions[data.order.status] || []).length" class="rounded-xl bg-ink/5 p-4 text-center font-bold">这个订单已经尘埃落定。</p></div></section><section class="sticker-card mt-6 bg-mint p-5"><h2 class="font-black">流转记录</h2><ol class="mt-3 space-y-2 text-sm"><li v-for="item in data.order.history" :key="item.id"><strong>{{ statusText[item.toStatus] }}</strong><span v-if="item.note" class="text-ink/55"> · {{ item.note }}</span></li></ol></section></aside></div></div></template>
